/**
 * Panel shown when user doesn't meet basic requirements (not logged in or not in clan).
 */
public class RequirementsPanel extends JPanel
{
	public enum RequirementType
	{
		NOT_LOGGED_IN,
		NOT_IN_CLAN
	}

	public RequirementsPanel(RequirementType type)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 10, Integer.MAX_VALUE));
		setBackground(PanelColors.getDarkGray());
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(80, 80, 100), 2),
			new EmptyBorder(15, 15, 15, 15)
		));

		switch (type)
		{
			case NOT_LOGGED_IN:
				buildNotLoggedInPanel();
				break;
			case NOT_IN_CLAN:
				buildNotInClanPanel();
				break;
		}
	}

	private void buildNotLoggedInPanel()
	{
		JLabel titleLabel = new JLabel("Login Required");
		titleLabel.setFont(new Font("Arial", Font.BOLD, 14));
		titleLabel.setForeground(new Color(150, 150, 200));
		titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(titleLabel);

		add(Box.createVerticalStrut(15));

		JLabel messageLabel = new JLabel("<html><div style='width:150px; text-align:center'>" +
			"Please log in to your OSRS account to use the Arceuus CC Plugin." +
			"</div></html>");
		messageLabel.setFont(new Font("Arial", Font.PLAIN, 11));
		messageLabel.setForeground(Color.WHITE);
		messageLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(messageLabel);

		addDiscordLink();
	}

	private void buildNotInClanPanel()
	{
		JLabel titleLabel = new JLabel("Clan Required");
		titleLabel.setFont(new Font("Arial", Font.BOLD, 14));
		titleLabel.setForeground(new Color(150, 150, 200));
		titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(titleLabel);

		add(Box.createVerticalStrut(15));

		JLabel messageLabel = new JLabel("<html><div style='width:150px; text-align:center'>" +
			"To use this plugin, please join the <b>Arceuus</b> Clan." +
			"</div></html>");
		messageLabel.setFont(new Font("Arial", Font.PLAIN, 11));
		messageLabel.setForeground(Color.WHITE);
		messageLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(messageLabel);

		add(Box.createVerticalStrut(15));

		JLabel instructionLabel = new JLabel("<html><div style='width:150px; text-align:center'>" +
			"Open the Clan tab and join our clan to get started." +
			"</div></html>");
		instructionLabel.setFont(new Font("Arial", Font.PLAIN, 10));
		instructionLabel.setForeground(PanelColors.getLightGray());
		instructionLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(instructionLabel);

		addDiscordLink();
	}

	private void addDiscordLink()
	{
		add(Box.createVerticalStrut(20));

		JLabel discordLabel = new JLabel("<html><div style='width:150px; text-align:center'>Join us on Discord:</div></html>");
		discordLabel.setFont(new Font("Arial", Font.BOLD, 11));
		discordLabel.setForeground(PanelColors.getLightGray());
		discordLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		add(discordLabel);

		add(Box.createVerticalStrut(5));

		JLabel linkLabel = new JLabel("<html><div style='width:150px; text-align:center'><u>discord.gg/Ka3bVn6nkW</u></div></html>");
		linkLabel.setFont(new Font("Arial", Font.PLAIN, 11));
		linkLabel.setForeground(PanelColors.UPCOMING_TITLE);
		linkLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		linkLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		linkLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse("https://discord.gg/Ka3bVn6nkW");
			}
		});
		add(linkLabel);
	}
}

package com.arceuuscc.plugin.util;

import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Locale;

public class DateTimeUtils
{
	public static final DateTimeFormatter ISO_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE_TIME;

	private static final DateTimeFormatter UTC_DATE_FORMATTER = DateTimeFormatter.ofPattern("dd-MMM-yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter UTC_MINUTE_FORMATTER = DateTimeFormatter.ofPattern("HH:mm 'UTC'");

	public static LocalDateTime nowUtc()
	{
		return LocalDateTime.now(ZoneOffset.UTC);
	}

	public static String currentUtcDate()
	{
		return UTC_DATE_FORMATTER.format(ZonedDateTime.now(ZoneOffset.UTC)).toUpperCase(Locale.ENGLISH);
	}

	public static String currentUtcTime()
	{
		return UTC_MINUTE_FORMATTER.format(ZonedDateTime.now(ZoneOffset.UTC));
	}

	public static String currentUtcTimestamp()
	{
		return currentUtcDate() + " " + currentUtcTime();
	}

	public static LocalDateTime parseDateTime(String isoTime)
	{
		if (isoTime == null)
		{
			return LocalDateTime.MIN;
		}
		try
		{
			return LocalDateTime.parse(isoTime, ISO_FORMATTER);
		}
		catch (DateTimeParseException e)
		{
			return LocalDateTime.MIN;
		}
	}
}

package com.arceuuscc.plugin.util;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;

/**
 * Utility methods for formatting display text.
 */
public final class FormatUtils
{
	private static final DateTimeFormatter DISPLAY_FORMATTER = DateTimeFormatter.ofPattern("EEE, MMM d 'at' HH:mm");
	private static final DateTimeFormatter INPUT_FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE_TIME;

	private FormatUtils() {}

	public static String formatEventTime(String isoTime)
	{
		if (isoTime == null)
		{
			return "Unknown";
		}
		try
		{
			LocalDateTime dateTime = LocalDateTime.parse(isoTime, INPUT_FORMATTER);
			return dateTime.format(DISPLAY_FORMATTER);
		}
		catch (DateTimeParseException e)
		{
			return isoTime;
		}
	}

	public static String formatDuration(int minutes)
	{
		if (minutes == 0)
		{
			return "Open-ended";
		}
		if (minutes < 60)
		{
			return minutes + " min";
		}
		int hours = minutes / 60;
		int mins = minutes % 60;
		if (hours < 24)
		{
			if (mins == 0)
			{
				return hours + "h";
			}
			return hours + "h " + mins + "m";
		}
		int days = hours / 24;
		hours = hours % 24;
		if (hours == 0)
		{
			return days + "d";
		}
		return days + "d " + hours + "h";
	}

	public static String formatCountdown(long totalSeconds)
	{
		if (totalSeconds < 0)
		{
			return "0s";
		}

		if (totalSeconds < 60)
		{
			return totalSeconds + "s";
		}

		long totalMinutes = totalSeconds / 60;

		if (totalMinutes < 60)
		{
			return totalMinutes + "m";
		}

		long hours = totalMinutes / 60;
		long minutes = totalMinutes % 60;
		if (hours < 24)
		{
			return hours + "h " + minutes + "m";
		}

		long days = hours / 24;
		hours = hours % 24;
		return days + "d " + hours + "h";
	}

	public static String formatEventCountdown(String startTimeIso, int durationMinutes, String status)
	{
		if (startTimeIso == null)
		{
			return null;
		}
		try
		{
			LocalDateTime startTime = LocalDateTime.parse(startTimeIso);
			LocalDateTime now = DateTimeUtils.nowUtc();

			if ("ACTIVE".equals(status))
			{
				if (durationMinutes <= 0)
				{
					return null;
				}
				LocalDateTime endTime = startTime.plusMinutes(durationMinutes);
				long seconds = ChronoUnit.SECONDS.between(now, endTime);
				return "Ends in: " + formatCountdown(seconds);
			}
			else if ("UPCOMING".equals(status))
			{
				long seconds = ChronoUnit.SECONDS.between(now, startTime);
				return "Starts in: " + formatCountdown(seconds);
			}
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
		return null;
	}

	public static String escapeHtml(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\"", "&quot;")
			.replace("\n", "<br>");
	}
}

package com.arceuuscc.plugin;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ArceuusCCPluginTest {
    public static void main(String[] args) throws Exception {
        System.out.println("[Arceuus CC] Loading plugin...");
        try {
            ExternalPluginManager.loadBuiltin(ArceuusCCPlugin.class);
            System.out.println("[Arceuus CC] Plugin registered with ExternalPluginManager");
        } catch (Exception e) {
            System.err.println("[Arceuus CC] Failed to load plugin: " + e.getMessage());
            e.printStackTrace();
        }
        System.out.println("[Arceuus CC] Starting RuneLite...");
        RuneLite.main(args);
    }
}
